import { describe, expect, it } from "vitest";
import { FINISHED_PREFIX, outcomeMessage, parseExperimentIdArgs, parseMetadataFlag, STILL_RUNNING_PREFIX, waitArguments, waitForExperiments, } from "./waitForExperiment.js";
const A = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
const B = "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb";
const POLL_MS = 10_000;
const TAG = { key: "bitfab-wait", value: "batch-1" };
function status(experimentId, overrides = {}) {
    return {
        experimentId,
        status: "pending",
        finishedCount: 0,
        remainingCount: 4,
        traceCount: 0,
        resumable: true,
        ...overrides,
    };
}
function sequence(values) {
    const queue = [...values];
    return () => (queue.length > 1 ? queue.shift() : queue[0]);
}
function fakeDeps(opts) {
    let clock = 0;
    const perExperiment = Object.fromEntries(Object.entries(opts.statuses ?? {}).map(([id, list]) => [
        id,
        sequence(list),
    ]));
    const nextLookup = sequence(opts.lookups ?? [[]]);
    const deps = {
        lines: [],
        reads: [],
        lookupLimits: [],
        readStatus: async (id) => {
            deps.reads.push(id);
            return perExperiment[id]();
        },
        findByMetadata: async (_tag, limit) => {
            deps.lookupLimits.push(limit);
            return nextLookup();
        },
        experimentUrl: (id) => `https://bitfab.test/experiments?experimentIds=${id}`,
        log: (line) => {
            deps.lines.push(line);
        },
        now: () => clock,
        sleep: async (ms) => {
            clock += ms;
        },
    };
    return deps;
}
function byIds(...experimentIds) {
    return { experimentIds, count: 1 };
}
describe("waitForExperiments", () => {
    it("returns once the experiment leaves pending, printing each change once", async () => {
        const deps = fakeDeps({
            statuses: {
                [A]: [
                    status(A, { finishedCount: 1, remainingCount: 3 }),
                    status(A, { finishedCount: 1, remainingCount: 3 }),
                    status(A, {
                        status: "completed",
                        finishedCount: 4,
                        remainingCount: 0,
                    }),
                ],
            },
        });
        const outcome = await waitForExperiments(byIds(A), 60_000, deps, POLL_MS);
        expect(outcome).toEqual({
            kind: "finished",
            experiments: [{ experimentId: A, status: "completed" }],
        });
        expect(deps.lines).toEqual([
            `[wait] ${A}: 1/4 replayed, status pending`,
            `[wait] ${A}: 4/4 replayed, status completed`,
        ]);
    });
    it("waits for every experiment and stops reading the ones already finished", async () => {
        const deps = fakeDeps({
            statuses: {
                [A]: [status(A, { status: "completed", remainingCount: 0 })],
                [B]: [
                    status(B),
                    status(B),
                    status(B, { status: "failed", remainingCount: 0 }),
                ],
            },
        });
        const outcome = await waitForExperiments(byIds(A, B), 60_000, deps, POLL_MS);
        expect(outcome).toEqual({
            kind: "finished",
            experiments: [
                { experimentId: A, status: "completed" },
                { experimentId: B, status: "failed" },
            ],
        });
        expect(deps.reads.filter((id) => id === A)).toHaveLength(1);
        expect(deps.reads.filter((id) => id === B)).toHaveLength(3);
    });
    it("hands back at the time limit while any experiment is pending", async () => {
        const deps = fakeDeps({
            statuses: {
                [A]: [status(A, { status: "completed" })],
                [B]: [status(B)],
            },
        });
        const outcome = await waitForExperiments(byIds(A, B), 35_000, deps, POLL_MS);
        expect(outcome).toEqual({
            kind: "still-running",
            experiments: [
                { experimentId: A, status: "completed" },
                { experimentId: B, status: "pending" },
            ],
            missingTagged: 0,
        });
    });
    it("keeps looking up a tag until as many experiments as --count appear, then waits for all", async () => {
        const deps = fakeDeps({
            lookups: [[], [A], [B, A]],
            statuses: {
                [A]: [status(A, { status: "completed" })],
                [B]: [status(B, { status: "completed" })],
            },
        });
        const outcome = await waitForExperiments({ experimentIds: [], metadata: TAG, count: 2 }, 60_000, deps, POLL_MS);
        expect(outcome.kind).toBe("finished");
        expect(outcome.experiments.map((e) => e.experimentId).sort()).toEqual([
            A,
            B,
        ]);
        expect(deps.lookupLimits).toEqual([2, 2, 2]);
        expect(deps.lines).toEqual([
            "[wait] Waiting for 2 more experiment(s) tagged bitfab-wait=batch-1. A cloud replay creates its experiment once its GitHub run starts.",
            `[wait] Experiment ${A}: https://bitfab.test/experiments?experimentIds=${A}`,
            `[wait] ${A}: 0/4 replayed, status completed`,
            `[wait] Experiment ${B}: https://bitfab.test/experiments?experimentIds=${B}`,
            `[wait] ${B}: 0/4 replayed, status completed`,
        ]);
    });
    it("does not finish while a tagged experiment is still missing, even when the found ones are done", async () => {
        const deps = fakeDeps({
            lookups: [[A]],
            statuses: { [A]: [status(A, { status: "completed" })] },
        });
        const outcome = await waitForExperiments({ experimentIds: [], metadata: TAG, count: 2 }, 20_000, deps, POLL_MS);
        expect(outcome).toEqual({
            kind: "still-running",
            experiments: [{ experimentId: A, status: "completed" }],
            missingTagged: 1,
        });
    });
    it("combines given IDs with tagged experiments without reading one twice", async () => {
        const deps = fakeDeps({
            lookups: [[A]],
            statuses: {
                [A]: [status(A, { status: "completed" })],
                [B]: [status(B, { status: "completed" })],
            },
        });
        const outcome = await waitForExperiments({ experimentIds: [A, B], metadata: TAG, count: 1 }, 60_000, deps, POLL_MS);
        expect(outcome.kind).toBe("finished");
        expect(deps.reads).toEqual([A, B]);
    });
    it("counts replayed traces without a total when the remaining count is unknown", async () => {
        const deps = fakeDeps({
            statuses: {
                [A]: [
                    status(A, {
                        status: "completed",
                        finishedCount: 2,
                        remainingCount: null,
                    }),
                ],
            },
        });
        await waitForExperiments(byIds(A), 0, deps, POLL_MS);
        expect(deps.lines).toEqual([`[wait] ${A}: 2 replayed, status completed`]);
    });
});
describe("outcomeMessage", () => {
    it("lists each experiment and says to read results in the same turn", () => {
        const lines = outcomeMessage(byIds(A, B), {
            kind: "finished",
            experiments: [
                { experimentId: A, status: "completed" },
                { experimentId: B, status: "completed" },
            ],
        });
        expect(lines[0]).toBe(`${FINISHED_PREFIX} 2 experiment(s) finished.`);
        expect(lines).toContain(`  ${A}: completed`);
        expect(lines.join("\n")).toContain("in this same turn");
        expect(lines.join("\n")).not.toContain("resumable");
    });
    it("points at the replay output when one did not complete", () => {
        const lines = outcomeMessage(byIds(A), {
            kind: "finished",
            experiments: [{ experimentId: A, status: "failed" }],
        });
        expect(lines.join("\n")).toContain("resumable");
    });
    it("tells the agent to run again with the same arguments", () => {
        const target = { experimentIds: [A], metadata: TAG, count: 3 };
        const lines = outcomeMessage(target, {
            kind: "still-running",
            experiments: [{ experimentId: A, status: "pending" }],
            missingTagged: 2,
        });
        expect(lines[0]).toContain(STILL_RUNNING_PREFIX);
        expect(lines[0]).toContain("3 experiment(s) have not finished");
        expect(lines[0]).toContain("Do not end your turn");
        expect(lines[0]).toContain(`run this command again with ${A} --metadata bitfab-wait=batch-1 --count 3`);
        expect(lines.join("\n")).toContain("--cloud-status");
        expect(lines.join("\n")).toContain("process is still running");
    });
});
describe("waitArguments", () => {
    it("leaves out --count when waiting for one tagged experiment", () => {
        expect(waitArguments({ experimentIds: [], metadata: TAG, count: 1 })).toBe("--metadata bitfab-wait=batch-1");
    });
});
describe("parseExperimentIdArgs", () => {
    it("accepts space- and comma-separated IDs, deduplicated", () => {
        expect(parseExperimentIdArgs([`${A},${B}`, A.toUpperCase()])).toEqual([
            A,
            B,
        ]);
    });
    it("rejects an ID that is not a UUID", () => {
        expect(() => parseExperimentIdArgs([A, "nope"])).toThrow('"nope" is not a valid experiment ID');
    });
});
describe("parseMetadataFlag", () => {
    it("splits on the first equals sign", () => {
        expect(parseMetadataFlag("bitfab-wait=a=b")).toEqual({
            key: "bitfab-wait",
            value: "a=b",
        });
    });
    it("rejects a pair with no key or no value", () => {
        expect(parseMetadataFlag("=x")).toBeNull();
        expect(parseMetadataFlag("x=")).toBeNull();
        expect(parseMetadataFlag("x")).toBeNull();
    });
});
